describe('Virtual Scroll List Performance', () => {
    beforeEach(() => {
        cy.visit('/virtual-scroll-list'); // Adjust the URL to your application's route
    });

    it('should display the first 20 rows without lag', () => {
        cy.get('.virtual-scroll-list') // Adjust the selector to your virtual scroll list
            .should('be.visible')
            .find('.row') // Adjust the selector to your row elements
            .should('have.length', 20); // Assuming the first 20 rows are rendered initially

        cy.get('.virtual-scroll-list').scrollTo('bottom'); // Scroll to load more rows
        cy.wait(1000); // Wait for rows to load

        cy.get('.virtual-scroll-list')
            .find('.row')
            .should('have.length.greaterThan', 20); // Ensure more rows are loaded
    });

    it('should handle scrolling to the bottom without performance issues', () => {
        cy.get('.virtual-scroll-list').scrollTo('bottom'); // Scroll to the bottom
        cy.wait(1000); // Wait for rows to load

        cy.get('.virtual-scroll-list')
            .find('.row')
            .should('have.length.greaterThan', 9800); // Ensure that nearly all rows are rendered
    });
});
